library(shiny)
library(readxl)
library(writexl)
library(DT)

# =========================
# UTILS
# =========================

load_conversation <- function(path) {
  
  if (!file.exists(path)) return(NULL)
  
  df <- read.delim(
    path,
    header = FALSE,
    sep = "\t",
    stringsAsFactors = FALSE,
    quote = ""
  )
  
  colnames(df) <- c("speaker", "text")
  
  df
}


get_context <- function(df, kwic, window = 5) {
  
  if (is.null(df)) return(NULL)
  
  idx <- which(grepl(kwic, df$text, fixed = TRUE))[1]
  
  if (is.na(idx)) return(NULL)
  
  start <- max(1, idx - window)
  end <- min(nrow(df), idx + window)
  
  df[start:end, ]
}


safe_id <- function(x) {
  x <- tolower(x)
  x <- gsub("[^a-z0-9]+", "_", x)
  x <- gsub("^_|_$", "", x)
  x
}

ensure_col <- function(df, col, default = "") {
  if (!col %in% names(df)) df[[col]] <- rep(default, nrow(df))
  df[[col]][is.na(df[[col]])] <- default
  df
}

ensure_bin_cols <- function(df, keys) {
  for (k in keys) {
    id <- safe_id(k)
    
    if (!id %in% names(df)) {
      df[[id]] <- rep(0, nrow(df))
    } else {
      df[[id]] <- as.numeric(df[[id]])
      df[[id]][is.na(df[[id]])] <- 0
    }
  }
  df
}

# =========================
# MAPPE (SOLO LABEL UI)
# =========================

INTERAZIONALI <- c(
  "Presa di turno",
  "Richiesta di accordo/conferma",
  "Accordo",
  "Conferma dell'attenzione",
  "Interruzione",
  "Cessione del turno",
  "Marcatura della conoscenza condivisa",
  "Richiesta di attenzione",
  "Strategia di cortesia"
)

METATESTUALI <- c(
  "Introduzione o ripresa del topic",
  "Chiusura del topic",
  "Prolettico",
  "Riformulazione",
  "Citazione/Discorso Riportato",
  "Esemplificazione",
  "Filler",
  "Marca di generalizzazione"
)

COGNITIVE <- c(
  "Marcatura dell'inferenza",
  "Modulazione del grado di confidenza",
  "Approssimazione",
  "Specificazione",
  "Attenuazione",
  "Intensificazione"
)

ALL_KEYS <- c(
  INTERAZIONALI,
  METATESTUALI,
  COGNITIVE
)

# =========================
# UI
# =========================

ui <- fluidPage(
  
  tags$head(
    
    tags$style(HTML("

      .drawer {
        position: fixed;
        right: 0;
        top: 0;
        width: 90vw;
        max-width: 1300px;
        height: 100%;
        background: #fff;
        border-left: 1px solid #ddd;
        padding: 18px 22px;
        overflow-y: auto;
        z-index: 99999;
      }

      .kwic {
        font-weight: 700;
        color: #1565c0;
      }

      .kwic-box {
        font-weight: 500;
        margin: 8px 0 12px 0;
        line-height: 1.6;
      }

      .micro-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 8px;
        margin-bottom: 4px;
      }

      .micro-label {
        display: flex;
        align-items: center;
        gap: 6px;
        line-height: 1.1;
      }

      .i {
        cursor: help;
        color: #999;
        font-weight: bold;
      }

      .material-box {
        display: flex;
        gap: 20px;
        align-items: flex-start;
        justify-content: space-between;
      }

      .material-left {
        flex: 1;
      }

      .material-right {
        width: 45%;
      }

      .save-fixed {
        position: sticky;
        top: 0;
        background: white;
        padding: 10px 0;
        z-index: 10000;
        border-bottom: 1px solid #eee;
      }

      .title-wrap {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 10px;
      }

      .title-wrap img {
        height: 44px;
      }

      .nav-row {
        display: flex;
        gap: 10px;
        margin-bottom: 10px;
      }

      table.dataTable tbody td {
        vertical-align: top;
      }

    ")),
    
    # warning chiusura pagina
    tags$script(HTML("
      let isSaved = true;

      $(document).on('click', '#save', function() {
        isSaved = true;
      });

      $(document).on('change', 'input, textarea', function() {
        isSaved = false;
      });

      window.addEventListener('beforeunload', function (e) {
        if (!isSaved) {
          e.preventDefault();
          e.returnValue = '';
        }
      });
    "))
  ),
  
  div(
    class = "title-wrap",
    
    tags$img(src = "logo.png"),
    
    h3("COLÀ - Console Online per L'Annotazione (dei segnali discorsivi)")
  ),
  
  fileInput("file", "Carica Excel/CSV"),
  
  downloadButton("download", "Esporta (.csv)"),
  
  hr(),
  
  DTOutput("table"),
  
  uiOutput("drawer")
)

# =========================
# SERVER
# =========================

server <- function(input, output, session) {
  
  df_r <- reactiveVal(NULL)
  
  idx <- reactiveVal(1)
  
  drawer <- reactiveVal(FALSE)
  
  conv_context <- reactiveVal(NULL)
  
  # ================= LOAD =================
  
  
  observeEvent(input$file, {
    
    ext <- tools::file_ext(input$file$name)
    
    df <- tryCatch({
      
      if (ext == "xlsx") {
        
        read_excel(input$file$datapath)
        
      } else {
        
        read.csv(
          input$file$datapath,
          stringsAsFactors = FALSE,
          check.names = FALSE
        )
      }
      
    }, error = function(e) NULL)
    
    if (is.null(df)) return()
    
    df <- as.data.frame(df)
    
    if ("labels" %in% names(df)) {
      
      df$labels <- gsub(";", "|", df$labels)
      
      df$labels <- gsub("\\s*\\|\\s*", "|", df$labels)
    }
    
    df <- ensure_col(df, "SD", "")
    df <- ensure_col(df, "labels", "")
    df <- ensure_col(df, "commenti", "")
    df <- ensure_col(df, "cumulo", 0) 
    df <- ensure_col(df, "cumulo_testo", "")
    
    df <- ensure_col(df, "annotation.audio_file", "")
    df <- ensure_col(df, "doc.full_conversation", "")
    df <- ensure_col(df, "doc.full_jefferson", "")
    
    df <- ensure_col(df, "Left", "")
    df <- ensure_col(df, "KWIC", "")
    df <- ensure_col(df, "Right", "")
    
    df <- ensure_bin_cols(df, ALL_KEYS)
    
    df_r(df)
    
    idx(1)
  })
  
  # ================= CURRENT =================
  
  cur <- reactive({
    req(df_r())
    df_r()[idx(), ]
  })
  
  # ================= TABLE =================
  
  output$table <- renderDT({
    
    df <- df_r()
    
    req(df)
    
    view <- data.frame(
      
      Occorrenza = paste0(
        df$Left,
        " <span class='kwic'>",
        df$KWIC,
        "</span> ",
        df$Right
      ),
      
      SD = df$SD,
      
      Funzioni = gsub("\\|", "; ", df$labels),
      
      Commento = substr(df$commenti, 1, 40),
      
      stringsAsFactors = FALSE
    )
    
    datatable(
      view,
      
      escape = FALSE,
      
      selection = "single",
      
      rownames = FALSE,
      
      options = list(
        scrollY = "600px",
        paging = FALSE,
        dom = "tip"
      )
    )
  })
  
  observeEvent(input$table_rows_selected, {
    
    idx(input$table_rows_selected)
    drawer(TRUE)
    
    r <- df_r()[idx(), ]
    
    path <- file.path(
      "www",
      "corpora",
      r$corpus,
      paste0(r$Reference, ".txt")
    )
    
    conv <- load_conversation(path)
    
    context <- get_context(conv, r$KWIC, window = 5)
    
    conv_context(context)
  })
  
  # ================= DRAWER =================
  
  output$drawer <- renderUI({
    
    if (!drawer()) return(NULL)
    
    r <- cur()
    
    req(r)
    
    current_idx <- idx()
    
    total_n <- nrow(df_r())
    
    tagList(
      
      div(
        class = "drawer",
        
        # ================= HEADER =================
        
        div(
          style="display:flex; justify-content:space-between; align-items:center;",
          
          h3(
            paste0(
              "Dettaglio — Occorrenza ",
              current_idx,
              "/",
              total_n
            )
          ),
          
          actionButton(
            "close",
            "✖",
            style="border:none; background:none; font-size:22px;"
          )
        ),
        
        hr(),
        
        # ================= NAV =================
        
        div(
          class = "nav-row",
          
          actionButton(
            "prev_occ",
            "⬅ Occorrenza precedente"
          ),
          
          actionButton(
            "next_occ",
            "Occorrenza successiva ➡"
          ),
          
          actionButton(
            "save",
            "💾 salva occorrenza",
            style = "font-weight:bold;"
          )
        ),
        
        hr(),
        
        # ================= MATERIALI + COMMENTI =================
        
        div(
          class = "material-box",
          
          # ================= LEFT =================
          
          div(
            class = "material-left",
            
            h4("Materiali"),
            
            if (nzchar(r$`annotation.audio_file`))
              tags$a(
                "🎧 Audio",
                href = r$`annotation.audio_file`,
                target = "_blank"
              ),
            
            br(),
            
            if (nzchar(r$`doc.full_conversation`))
              tags$a(
                "📄 Conversazione",
                href = r$`doc.full_conversation`,
                target = "_blank"
              ),
            
            br(),
            
            if (nzchar(r$`doc.full_jefferson`))
              tags$a(
                "📄 Jefferson",
                href = r$`doc.full_jefferson`,
                target = "_blank"
              ),
            
            hr(),
            
            fluidRow(
              
              # ===== OCCORRENZA + SD =====
              
              column(
                8,
                
                hr(),
                
                h4("Contesto conversazione"),
                
                if (is.null(conv_context())) {
                  
                  HTML("<i>Contesto non disponibile</i>")
                  
                } else {
                  
                  HTML(paste0(
                    "<table style='width:100%; border-collapse:collapse;'>",
                    paste0(
                      "<tr>",
                      "<td style='width:80px; color:#666'>",
                      conv_context()$speaker,
                      "</td>",
                      "<td>",
                      conv_context()$text,
                      "</td>",
                      "</tr>",
                      collapse = ""
                    ),
                    "</table>"
                  ))
                  
                },
                
                radioButtons(
                  "sd",
                  "SD",
                  choices = c("Non SD", "SD"),
                  selected = character(0),
                  inline = TRUE
                )
              ),
              
              # ===== CUMULO =====
              
              column(
                4,
                
                checkboxInput(
                  "cumulo",
                  "Cumulo",
                  value = !is.na(r$cumulo) &&
                    as.numeric(r$cumulo) == 1
                ),
                
                conditionalPanel(
                  condition = "input.cumulo == true",
                  
                  textAreaInput(
                    "cumulo_testo",
                    NULL,
                    value = ifelse(
                      is.na(r$cumulo_testo),
                      "",
                      r$cumulo_testo
                    ),
                    width = "100%",
                    height = "70px",
                    placeholder = "Elementi in cumulo..."
                  )
                )
              )
            )
          ),
          
          # ================= RIGHT =================
          
          div(
            class = "material-right",
            
            textAreaInput(
              "commenti",
              "Commenti",
              value = r$commenti,
              width = "100%",
              height = "90px"
            )
          )
        ),
      
        
        # ================= MICROFUNZIONI =================
        
        fluidRow(
          
          column(
            4,
            
            h4("Interazionali"),
            
            lapply(INTERAZIONALI, function(k) {
              
              id <- safe_id(k)
              
              val <- r[[id]]
              
              val <- !is.na(val) && as.numeric(val) == 1
              
              div(
                class="micro-row",
                
                div(
                  class="micro-label",
                  
                  k,
                  
                  span(
                    "ℹ",
                    class="i",
                    title = k
                  )
                ),
                
                checkboxInput(
                  id,
                  NULL,
                  value = val
                )
              )
            })
          ),
          
          column(
            4,
            
            h4("Metatestuali"),
            
            lapply(METATESTUALI, function(k) {
              
              id <- safe_id(k)
              
              val <- r[[id]]
              
              val <- !is.na(val) && as.numeric(val) == 1
              
              div(
                class="micro-row",
                
                div(
                  class="micro-label",
                  
                  k,
                  
                  span(
                    "ℹ",
                    class="i",
                    title = k
                  )
                ),
                
                checkboxInput(
                  id,
                  NULL,
                  value = val
                )
              )
            })
          ),
          
          column(
            4,
            
            h4("Cognitive"),
            
            lapply(COGNITIVE, function(k) {
              
              id <- safe_id(k)
              
              val <- r[[id]]
              
              val <- !is.na(val) && as.numeric(val) == 1
              
              div(
                class="micro-row",
                
                div(
                  class="micro-label",
                  
                  k,
                  
                  span(
                    "ℹ",
                    class="i",
                    title = k
                  )
                ),
                
                checkboxInput(
                  id,
                  NULL,
                  value = val
                )
              )
            })
          )
        ),
        
        hr(),
        
        actionButton("close", "chiudi")
      )
    )
  })
  
  # ================= CLOSE =================
  
  observeEvent(input$close, {
    drawer(FALSE)
  })
  
  # ================= PREV/NEXT =================
  
  observeEvent(input$prev_occ, {
    
    if (idx() > 1) {
      idx(idx() - 1)
    }
  })
  
  observeEvent(input$next_occ, {
    
    req(df_r())
    
    if (idx() < nrow(df_r())) {
      idx(idx() + 1)
    }
  })
  
  # ================= SYNC =================
  
  observe({
    
    r <- cur()
    
    if (is.null(r)) return()
    
    selected_sd <- if (
      is.null(r$SD) ||
      is.na(r$SD) ||
      !nzchar(as.character(r$SD))
    ) {
      character(0)
    } else {
      as.character(r$SD)
    }
    
    updateRadioButtons(
      session,
      "sd",
      selected = selected_sd
    )
    
    updateTextAreaInput(
      session,
      "commenti",
      value = ifelse(is.na(r$commenti), "", r$commenti)
    )
    
    updateCheckboxInput( session, "cumulo", value = !is.na(r$cumulo) && as.numeric(r$cumulo) == 1 ) 
    
    updateTextAreaInput( session, "cumulo_testo", value = ifelse(is.na(r$cumulo_testo), "", r$cumulo_testo) )
    
    
    for (k in ALL_KEYS) {
      
      id <- safe_id(k)
      
      val <- r[[id]]
      
      val <- suppressWarnings(as.numeric(val))
      
      updateCheckboxInput(
        session,
        id,
        value = !is.na(val) && val == 1
      )
    }
  })
  
  # ================= SAVE =================
  
  observeEvent(input$save, {
    
    df <- df_r()
    
    i <- idx()
    
    df$SD[i] <- if (is.null(input$sd)) "" else input$sd
    
    df$commenti[i] <- input$commenti
    
    df$cumulo[i] <- ifelse(
      isTRUE(input$cumulo),
      1,
      0
    ) 
    df$cumulo_testo[i] <- ifelse( isTRUE(input$cumulo), input$cumulo_testo, "" )
    
    selected <- c()
    
    for (k in ALL_KEYS) {
      
      id <- safe_id(k)
      
      val <- isTRUE(input[[id]])
      
      df[[id]][i] <- ifelse(val, 1, 0)
      
      if (val) selected <- c(selected, k)
    }
    
    # salva labels con NOMI UI
    df$labels[i] <- paste(selected, collapse = "|")
    
    df_r(df)
  })
  
  # ================= DOWNLOAD =================
  
  output$download <- downloadHandler(
    
    filename = function() "annotato.xlsx",
    
    content = function(file) {
      
      write_xlsx(df_r(), file)
    }
  )
}

shinyApp(ui, server)
